    incomeAboveLimit: 'Entrada sur la limita (CHF {value})',
    eligible: 'Dretg a la reducziun da premias: CHF {value}/mais',
    // TODO(rm): provisorisch — von Muttersprachler:in gegenlesen (E9, 16.09.2026).
